insert into public.dersler(id,hoca,sira,data)
select x->>'id','',(x->>'sira')::int, jsonb_build_object('ad',x->'ad','kat',x->'kat','hafta',x->'hafta','fiyat',x->'fiyat','kaz',x->'kaz','duzey',x->'duzey',
 'plan',(select jsonb_agg(jsonb_build_object('konu',k,'kazanim','') order by n) from jsonb_array_elements(x->'konu') with ordinality t(k,n)))
from jsonb_array_elements('[{"id":"d1","sira":1,"ad":"Minecraft Education Edition","kat":"Kodlama","hafta":8,"fiyat":3200,"kaz":["Blok kodlama ile dünya tasarlar","Takım halinde problem çözer","Basit algoritmalar kurar","Takım projesini sunar"],"duzey":["İlkokul","Ortaokul"],"konu":["Dünyaya giriş","Agent ile hareket","Döngüler","Koşullar","Uygulama ve tekrar 5","Uygulama ve tekrar 6","Uygulama ve tekrar 7","Final projesi ve değerlendirme"]},{"id":"d2","sira":2,"ad":"YouTube ve Sosyal Medya","kat":"Medya","hafta":8,"fiyat":2800,"kaz":["Güvenli ve etik paylaşım yapar","Video senaryosu yazar","Temel kurgu yapar","Kişisel bilgilerini korur"],"duzey":["Ortaokul","Lise"],"konu":["Dijital güvenlik","İçerik fikri","Senaryo","Çekim teknikleri","Uygulama ve tekrar 5","Uygulama ve tekrar 6","Uygulama ve tekrar 7","Final projesi ve değerlendirme"]},{"id":"d3","sira":3,"ad":"Python Ortaokul","kat":"Kodlama","hafta":12,"fiyat":4500,"kaz":["Değişken ve koşulları kullanır","Döngü yazar","Küçük bir oyun geliştirir","Hatalarını bulup düzeltir"],"duzey":["Ortaokul"],"konu":["Python ile tanışma","Değişkenler","Koşullar","Döngüler","Listeler","Fonksiyonlar","Uygulama ve tekrar 7","Uygulama ve tekrar 8","Uygulama ve tekrar 9","Uygulama ve tekrar 10","Uygulama ve tekrar 11","Final projesi ve değerlendirme"]},{"id":"d4","sira":4,"ad":"Python Lise","kat":"Kodlama","hafta":12,"fiyat":5200,"kaz":["Fonksiyon ve veri yapıları kullanır","Dosya işlemleri yapar","Proje sunar","Hata ayıklama yapar"],"duzey":["Lise"],"konu":["Temel söz dizimi","Veri tipleri","Fonksiyonlar","Sözlükler","Dosyalar","Nesne tabanlı giriş","Uygulama ve tekrar 7","Uygulama ve tekrar 8","Uygulama ve tekrar 9","Uygulama ve tekrar 10","Uygulama ve tekrar 11","Final projesi ve değerlendirme"]},{"id":"d5","sira":5,"ad":"Scratch","kat":"Kodlama","hafta":8,"fiyat":2600,"kaz":["Animasyon hazırlar","Olay tabanlı düşünür","Kendi oyununu yapar","Projesini arkadaşlarına anlatır"],"duzey":["İlkokul","Ortaokul"],"konu":["Sahne ve karakter","Hareket","Olaylar","Döngüler","Uygulama ve tekrar 5","Uygulama ve tekrar 6","Uygulama ve tekrar 7","Final projesi ve değerlendirme"]},{"id":"d6","sira":6,"ad":"İngilizce","kat":"Dil","hafta":12,"fiyat":4800,"kaz":["Günlük konuşma kurar","Kelime dağarcığını geliştirir","Kısa metin yazar","Basit sunum yapar"],"duzey":["İlkokul","Ortaokul","Lise"],"konu":["Tanışma","Günlük rutin","Okul hayatı","Hobiler","Uygulama ve tekrar 5","Uygulama ve tekrar 6","Uygulama ve tekrar 7","Uygulama ve tekrar 8","Uygulama ve tekrar 9","Uygulama ve tekrar 10","Uygulama ve tekrar 11","Final projesi ve değerlendirme"]},{"id":"d7","sira":7,"ad":"Bireysel Mentörlük","kat":"Mentörlük","hafta":8,"fiyat":6000,"kaz":["Kişisel hedef belirler","Çalışma planı oluşturur","Güçlü yönlerini tanır","Gelişimini düzenli değerlendirir"],"duzey":["Lise","Üniversite","Mezun"],"konu":["Tanışma ve hedef","Güçlü yönler","Plan","Takip","Uygulama ve tekrar 5","Uygulama ve tekrar 6","Uygulama ve tekrar 7","Final projesi ve değerlendirme"]},{"id":"d8","sira":8,"ad":"Öğrenci Koçluğu","kat":"Koçluk","hafta":12,"fiyat":6400,"kaz":["Zaman yönetimi yapar","Sınav kaygısıyla başa çıkma yolları öğrenir","Verimli çalışma yöntemlerini uygular","Haftalık çalışma planı yapar"],"duzey":["Ortaokul","Lise"],"konu":["İhtiyaç analizi","Zaman yönetimi","Verimli çalışma","Motivasyon","Uygulama ve tekrar 5","Uygulama ve tekrar 6","Uygulama ve tekrar 7","Uygulama ve tekrar 8","Uygulama ve tekrar 9","Uygulama ve tekrar 10","Uygulama ve tekrar 11","Final projesi ve değerlendirme"]}]'::jsonb) x
